// Construye filas para la hoja Historial (chunked para evitar el límite de celda)
const items = $input.all();
const data = items.length > 1 ? items.map(i => i.json) : (items[0] ? items[0].json : {});

const modulo = "catering";
const fecha = new Date().toISOString();
const exec_id = modulo.slice(0,3).toUpperCase() + "-" + Date.now().toString(36).slice(-5).toUpperCase();

let etiqueta = "Asignación", resumen = "";
try {
  if (modulo === "software") {
    const rs = data.resumen || {};
    etiqueta = (data.resumen_proyectos && data.resumen_proyectos[0] && data.resumen_proyectos[0].nombre) || "Asignación";
    resumen = (rs.tareas_asignadas ?? 0) + "/" + (rs.total_tareas ?? 0) + " tareas · " + (rs.horas_totales_asignadas ?? 0) + "h";
  } else if (modulo === "guardias") {
    const v = data.validacion || {};
    etiqueta = ("Calendario " + (data.periodo || "")).trim();
    resumen = (data.total_puestos_cubiertos ?? 0) + "/" + (data.total_puestos_necesarios ?? 0) + " puestos · " + (v.total_violaciones_hard ?? 0) + " violaciones";
  } else {
    const list = Array.isArray(data) ? data : [];
    const eventos = [...new Set(list.map(r => r.event_id).filter(Boolean))];
    etiqueta = "Eventos: " + (eventos.join(", ") || "—");
    resumen = list.length + " camareros · " + eventos.length + " evento(s)";
  }
} catch (e) {}

const full = JSON.stringify(data);
const SIZE = 40000;
const chunks = [];
for (let i = 0; i < full.length; i += SIZE) chunks.push(full.slice(i, i + SIZE));
if (!chunks.length) chunks.push("");

return chunks.map((chunk, idx) => ({ json: { exec_id, modulo, fecha, etiqueta, resumen, idx, total: chunks.length, chunk } }));
